-- Initial preview catalog, NOT a completed six-brand launch.
-- Review source URLs and nutrition values before running. Prices are unknown (NULL).
-- Fresh catalog only; aborts rather than overwriting existing products.
BEGIN;
SET LOCAL search_path = public;
LOCK TABLE public.drinks, public.drink_variants IN EXCLUSIVE MODE;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM public.drinks) OR EXISTS (SELECT 1 FROM public.drink_variants) THEN RAISE EXCEPTION 'Catalog already contains data. No changes applied.'; END IF; END $$;
SET CONSTRAINTS ALL IMMEDIATE;
COMMIT;
SELECT (SELECT count(*) FROM public.drinks) AS drinks, (SELECT count(*) FROM public.drink_variants) AS variants;
